import random, itertools
n=14
def check(edges):
    # girth >=5: no cycles of length 3 or 4
    # build adjacency
    adj=[[0]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v]=adj[v][u]=1
    # check triangles
    for a,b,c in itertools.combinations(range(n),3):
        if adj[a][b] and adj[b][c] and adj[c][a]:
            return False
    # check 4-cycles
    for a,b,c,d in itertools.combinations(range(n),4):
        # need cycle a-b-c-d-a with edges present and no chords? just any 4-cycle existence
        if adj[a][b] and adj[b][c] and adj[c][d] and adj[d][a]:
            return False
    # edges >=16
    if len(edges)<16:
        return False
    # 5-colorable: try greedy coloring up to 5 colors
    colors=[-1]*n
    order=sorted(range(n), key=lambda x: sum(adj[x]))
    def dfs(i):
        if i==n:
            return True
        v=order[i]
        used=set()
        for u in range(n):
            if adj[v][u] and colors[u]!=-1:
                used.add(colors[u])
        for c in range(5):
            if c not in used:
                colors[v]=c
                if dfs(i+1):
                    return True
                colors[v]=-1
        return False
    if not dfs(0):
        return False
    return True

all_edges=list(itertools.combinations(range(n),2))
for _ in range(20000):
    edges=random.sample(all_edges, random.randint(16,30))
    if check(edges):
        print('found', edges)
        break
else:
    print('none')
